// Aplana el RSS ya convertido a JSON en una lista de noticias individuales
// y calcula un slug ESTABLE (hash del link) para que re-ejecutar el pipeline
// sobre la misma noticia siempre produzca el mismo archivo -> GitHub rechaza
// el duplicado en el paso de commit en vez de publicarlo dos veces.

function firstText(v) {
  if (v === undefined || v === null) return '';
  if (Array.isArray(v)) return firstText(v[0]);
  if (typeof v === 'object') return v._ || '';
  return String(v);
}

function slugify(str) {
  return str.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '')
    .slice(0, 60);
}

function hashStr(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash + str.charCodeAt(i)) >>> 0;
  }
  return hash.toString(16).slice(0, 8);
}

const raw = $input.first().json;
const channel = (raw.rss && raw.rss.channel) ? (raw.rss.channel[0] || raw.rss.channel) : {};
const rawItems = channel.item || [];
const list = Array.isArray(rawItems) ? rawItems : [rawItems];

return list.slice(0, 5).map((it) => {
  const title = firstText(it.title);
  const link = firstText(it.link);
  const pubDate = firstText(it.pubDate);
  const sourceObj = Array.isArray(it.source) ? it.source[0] : it.source;
  const sourceName = (sourceObj && sourceObj._) || (typeof sourceObj === 'string' ? sourceObj : 'Fuente');
  const slug = `${slugify(title)}-${hashStr(link || title)}`;
  return { json: { title, link, pubDate, sourceName: String(sourceName), slug } };
});

